export function parseCSV(text) {
  const rows=[]; let row=[],cell='',quote=false;
  for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}
  if(quote)throw Error('Tanda kutip CSV tidak ditutup.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);
  if(rows.length<2)throw Error('CSV harus memiliki header dan baris data.');const head=rows.shift().map(x=>x.trim().replace(/^\uFEFF/,''));if(new Set(head).size!==head.length)throw Error('Header CSV duplikat.');
  for(const key of ['sample_id','label','score','model','dataset','threshold'])if(!head.includes(key))throw Error(`Kolom wajib tidak ditemukan: ${key}`);
  const seen=new Set(),truth=new Map();return rows.map((r,i)=>{if(r.length!==head.length)throw Error(`Jumlah kolom tidak sesuai pada baris ${i+2}.`);const o=Object.fromEntries(head.map((k,j)=>[k,r[j].trim()]));for(const k of ['sample_id','model','dataset','label','score','threshold'])if(o[k]==='')throw Error(`Kolom ${k} kosong pada baris ${i+2}.`);for(const k of ['label','score','threshold'])o[k]=Number(o[k]);if(![0,1].includes(o.label)||!Number.isFinite(o.score)||!Number.isFinite(o.threshold))throw Error(`Label/skor/threshold tidak valid pada baris ${i+2}.`);const id=JSON.stringify([o.dataset,o.model,o.seed||'',o.sample_id]);if(seen.has(id))throw Error(`sample_id duplikat dalam model/dataset/seed: ${o.sample_id}`);seen.add(id);const truthKey=JSON.stringify([o.dataset,o.seed||'',o.sample_id]);if(truth.has(truthKey)&&truth.get(truthKey)!==o.label)throw Error(`Label sample_id berbeda antar model: ${o.sample_id}`);truth.set(truthKey,o.label);return o;});
}
export function metrics(rows,threshold){
 if(!rows.length)throw Error('Tidak ada sampel.');if(!Number.isFinite(threshold))throw Error('Threshold harus finite.');let tp=0,tn=0,fp=0,fn=0;for(const r of rows){if(![0,1].includes(r.label)||!Number.isFinite(r.score))throw Error('Label/skor tidak valid.');if(r.label===1){r.score>=threshold?tp++:fn++;}else{r.score>=threshold?fp++:tn++;}}
 const p=tp+fn,n=tn+fp,div=(a,b)=>b?a/b:null;let roc=[{fpr:0,tpr:0}],pr=[{recall:0,precision:1}],auc=null,eer=null,ap=null;
 if(p&&n){let a=0,b=0,area=0,apv=0;const sorted=[...rows].sort((x,y)=>y.score-x.score);for(let i=0;i<sorted.length;){const score=sorted[i].score,oa=a,ob=b;while(i<sorted.length&&sorted[i].score===score){sorted[i].label?a++:b++;i++;}area+=(b-ob)/n*(a+oa)/p/2;apv+=(a-oa)/p*a/(a+b);roc.push({fpr:b/n,tpr:a/p});pr.push({recall:a/p,precision:a/(a+b)});}auc=area;ap=apv;for(let i=1;i<roc.length;i++){const a=roc[i-1],b=roc[i],da=a.fpr+a.tpr-1,db=b.fpr+b.tpr-1;if(da<=0&&db>=0){const w=db===da?0:-da/(db-da);eer=a.fpr+w*(b.fpr-a.fpr);break;}}}
 const tpr=div(tp,p),tnr=div(tn,n),precision=div(tp,tp+fp),recall=tpr;const den=Math.sqrt((tp+fp)*(tp+fn)*(tn+fp)*(tn+fn));
 return {n:rows.length,p,n_real:n,tp,tn,fp,fn,threshold,accuracy:(tp+tn)/rows.length,balanced_accuracy:p&&n?(tpr+tnr)/2:null,precision,recall,f1:div(2*tp,2*tp+fp+fn),fpr:div(fp,n),fnr:div(fn,p),mcc:den?(tp*tn-fp*fn)/den:null,auc,eer,ap,roc,pr,tpr_at_5:p&&n?Math.max(...roc.filter(x=>x.fpr<=.05).map(x=>x.tpr)):null};
}
export function groupMetrics(rows,override=null){const g=new Map();for(const r of rows){const key=JSON.stringify([r.dataset,r.model,r.seed||'']);if(!g.has(key))g.set(key,[]);g.get(key).push(r);}return [...g].map(([key,rs])=>{const [dataset,model,seed]=JSON.parse(key);const th=new Set(rs.map(x=>x.threshold));if(th.size!==1)throw Error(`Threshold berbeda dalam ${model}/${dataset}/${seed}.`);return {dataset,model,seed,rows:rs,...metrics(rs,override??rs[0].threshold)};});}
export function paired(a,b){if(a.dataset!==b.dataset||a.seed!==b.seed)return null;const bb=new Map(b.rows.map(r=>[r.sample_id,r]));if(a.rows.length!==b.rows.length||a.rows.some(r=>!bb.has(r.sample_id)))return null;let aOnly=0,bOnly=0,bothWrong=0,bothRight=0;for(const r of a.rows){const q=bb.get(r.sample_id);if(q.label!==r.label)throw Error('Label berbeda pada sampel berpasangan.');const ca=Number(r.score>=a.threshold)===r.label,cb=Number(q.score>=b.threshold)===q.label;if(ca&&cb)bothRight++;else if(!ca&&!cb)bothWrong++;else if(ca)aOnly++;else bOnly++;}return {aOnly,bOnly,bothWrong,bothRight,n:a.rows.length};}
